package com.tracker.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.time.*;
@Entity @Table(name="courses") @Getter @Setter @NoArgsConstructor
public class Course { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=150) private String courseName; @NotBlank @Size(max=100) private String provider; @PastOrPresent private LocalDate completionDate; private LocalDate startDate; @NotNull @Min(1) private Integer duration; @Size(max=1000) private String description; @Size(max=100) private String instructor; @Size(max=80) private String category; @Size(max=30) private String status="COMPLETED"; @Size(max=1000) private String notes; @Pattern(regexp="^$|^https?://\\S+$") private String courseUrl; private LocalDateTime createdAt; @ManyToOne(optional=false) @JoinColumn(name="user_id") @JsonIgnore private User user; @PrePersist void created(){createdAt=LocalDateTime.now();} }
